class TIPvXFilterType(TextualConvention, Integer32):
    description = 'Specifies the set of available match criteria for a filter policy.\n\n         - normal                  (0): Allows all match criteria except of:\n                                        - Source MAC, Packet length.\n         - srcMac                  (1): Allows matching Source MAC and all match criteria for type normal except of:\n                                        - Source IP, DSCP and all IP Options in IPv4 filters.\n                                        - Source IP in IPv6 filters.\n         - pktLen                  (2): Allows matching Packet length and all match criteria for type normal except of:\n                                        - DSCP and IP Options in IPv4 filters.\n                                        - Flow Label in IPv6 filters.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(0, 1, 2, 3))
    namedValues = NamedValues(("normal", 0), ("srcMac", 1), ("pktLen", 2), ("reserved3", 3))

