tMacFltrEntryActRedirectURL = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 21, 83, 1, 8), TmnxHttpRedirectUrl().clone(hexValue="")).setMaxAccess("readcreate")
