tMacFltrEntryActEsi = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 21, 83, 1, 9), TFilterEsi().clone(hexValue="00000000000000000000")).setMaxAccess("readcreate")
