tMacFltrEntryActRateLimit = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 21, 83, 1, 11), TFilterEntryActionRateLimit().clone(0)).setUnits('kilobps').setMaxAccess("readcreate")
