tIPvXFltrEntryActNatPolicyName = MibTableColumn((1, 3, 6, 1, 4, 1, 6527, 3, 1, 2, 21, 85, 1, 19), TNamedItemOrEmpty().clone('')).setMaxAccess("readcreate")
